// Generated by tooling/unicode-cases/normalization.ts; Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [2075261381, 3175287237, 662421957, 2691434949, 1810698693, 3113712069, 3977114053, 762036677, 1740382661, 160983493, 3092255173, 1805173189, 1002615237, 3372675525, 3279278533, 409164229];
const blocks = ["NFC U+100000-U+100FFF", "NFC U+101000-U+101FFF", "NFC U+102000-U+102FFF", "NFC U+103000-U+103FFF", "NFC U+104000-U+104FFF", "NFC U+105000-U+105FFF", "NFC U+106000-U+106FFF", "NFC U+107000-U+107FFF", "NFC U+108000-U+108FFF", "NFC U+109000-U+109FFF", "NFC U+10A000-U+10AFFF", "NFC U+10B000-U+10BFFF", "NFC U+10C000-U+10CFFF", "NFC U+10D000-U+10DFFF", "NFC U+10E000-U+10EFFF", "NFC U+10F000-U+10FFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 1048576 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFC");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
